                let error = format!("{error:#}");
                tracing::error!(
                    error = %error,
                    "coordinator prompt nudge: sent but failed to persist the new hash; will re-nudge next restart"
                );
                audit::record_event(
                    "coordinator_prompt_nudge",
                    &json!({
                        "outcome": "sent_unpersisted",
                        "session_name": record.session_name,
                        "error": error,
                    }),
                );
